  error?.let{Text(it,color=MaterialTheme.colorScheme.error,modifier=Modifier.padding(top=10.dp))};Spacer(Modifier.height(18.dp));Button(enabled=!busy,onClick={val validation=AuthValidator.validate(AuthForm(mode,phone,password,displayName,question,answer,challenge));if(validation!=null){error=validation}else scope.launch{busy=true;error=null;runCatching{withContext(Dispatchers.IO){when(mode){AuthMode.Login->auth.login(phone,password,android.os.Build.MODEL).let{if(it.tokens!=null)it.tokens else{challenge=it.challengeId;serverQuestion=it.question.orEmpty();mode=AuthMode.Verify;null}};AuthMode.Register->auth.register(phone,displayName,password,question,answer,android.os.Build.MODEL);AuthMode.Verify->auth.verifyDevice(challenge!!,answer)}}}.onSuccess{if(it!=null)onAuthenticated(it)}.onFailure{error=it.message};busy=false}},modifier=Modifier.fillMaxWidth().testTag("auth.submit")){Text(stringResource(if(busy)R.string.auth_working else when(mode){AuthMode.Login->R.string.auth_sign_in;AuthMode.Register->R.string.auth_sign_up;AuthMode.Verify->R.string.auth_verify_device}))}
