private data class HostTab(val title:String,val icon:Int)
@Composable private fun HostTabs(tokens:SessionTokens,onLogout:()->Unit){val tabs=listOf(HostTab(stringResource(R.string.tab_message),R.drawable.tek_message),HostTab(stringResource(R.string.tab_ai),R.drawable.tek_ai),HostTab(stringResource(R.string.tab_me),R.drawable.tek_me));var selected by remember{mutableIntStateOf(0)};BoxWithConstraints(Modifier.fillMaxSize()){val tablet=maxWidth>=TekDesign.wideBreakpoint.dp;val content: @Composable () -> Unit = {when(selected){0->MessagesHome(tokens);1->EmptyFeature(stringResource(R.string.tab_ai),stringResource(R.string.ai_plugin_description));else->Profile(tokens,onLogout)}};if(tablet){Row(Modifier.fillMaxSize()){NavigationRail(header={Text("TEKtalk",fontWeight=FontWeight.Bold,modifier=Modifier.padding(12.dp))}){tabs.forEachIndexed{i,t->NavigationRailItem(modifier=Modifier.testTag("tab.$i"),selected=selected==i,onClick={selected=i},icon={Icon(painterResource(t.icon),contentDescription=null)},label={Text(t.title)})}};VerticalDivider();Box(Modifier.weight(1f)){content()}}}else{Scaffold(bottomBar={NavigationBar{tabs.forEachIndexed{i,t->NavigationBarItem(modifier=Modifier.testTag("tab.$i"),selected=selected==i,onClick={selected=i},icon={Icon(painterResource(t.icon),contentDescription=null)},label={Text(t.title)})}}}){p->Box(Modifier.padding(p)){content()}}}}}
