 Column(Modifier.fillMaxSize()){val callUnavailable=stringResource(R.string.call_not_available);TopAppBar(title={Text("TEKtalk Chat")},navigationIcon={TextButton(onClick=onBack){Text("‹")}},actions={TextButton(onClick={status=callUnavailable}){Text(stringResource(R.string.call_title))}});Column(Modifier.padding(horizontal=14.dp)){OutlinedTextField(conversation,{conversation=it},Modifier.fillMaxWidth().testTag("chat.conversation"),label={Text(stringResource(R.string.message_conversation_uuid))},singleLine=true);OutlinedTextField(recipient,{recipient=it},Modifier.fillMaxWidth().testTag("chat.recipient"),label={Text(stringResource(R.string.message_recipient_uuid))},singleLine=true);TextButton(modifier=Modifier.testTag("chat.sync"),onClick={load()}){Text(stringResource(R.string.message_sync_history))};Text(status,style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)};LazyColumn(Modifier.weight(1f).padding(horizontal=12.dp)){items(messages,key={it.id}){m->val mine=m.senderId==tokens.userId;Row(Modifier.fillMaxWidth(),horizontalArrangement=if(mine)Arrangement.End else Arrangement.Start){Surface(color=if(mine)MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.surfaceVariant,shape=RoundedCornerShape(TekDesign.bubbleRadius.dp),modifier=Modifier.widthIn(max=420.dp).padding(vertical=3.dp)){Text(m.body,Modifier.padding(12.dp),color=if(mine)MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.onSurfaceVariant)}}}};Row(Modifier.padding(12.dp),verticalAlignment=Alignment.CenterVertically){OutlinedTextField(draft,{draft=it},Modifier.weight(1f).testTag("chat.draft"),placeholder={Text(stringResource(R.string.message_compose))});Spacer(Modifier.width(8.dp));Button(modifier=Modifier.testTag("chat.send"),enabled=draft.isNotBlank()&&conversation.isNotBlank()&&recipient.isNotBlank(),onClick={val outgoing=ChatDraft(conversation,recipient,draft);val validation=ChatLogic.validationError(outgoing);if(validation!=null){status=val